CREATE OR REPLACE VIEW v_top_customers AS SELECT u.user_id,u.full_name,COUNT(DISTINCT b.booking_id) bookings,COALESCE(SUM(CASE p.status WHEN 'paid' THEN p.amount WHEN 'refunded' THEN -p.amount ELSE 0 END),0) net_spend FROM users u JOIN bookings b ON b.customer_id=u.user_id JOIN payments p USING(booking_id) GROUP BY u.user_id,u.full_name ORDER BY net_spend DESC LIMIT 5;
CREATE OR REPLACE VIEW v_category_revenue AS SELECT c.name category,COUNT(*) rentals,SUM(b.total_amount) revenue,ROUND(AVG(b.total_amount),2) avg_booking FROM bookings b JOIN vehicles v USING(vehicle_id) JOIN vehicle_categories c USING(category_id) WHERE b.status='completed' GROUP BY c.name;
CREATE OR REPLACE VIEW v_vehicle_ranks AS SELECT category,reg_number,rentals,RANK() OVER(PARTITION BY category ORDER BY rentals DESC) rank_in_category FROM(SELECT c.name category,v.reg_number,COUNT(b.booking_id) rentals FROM vehicles v JOIN vehicle_categories c USING(category_id) LEFT JOIN bookings b ON b.vehicle_id=v.vehicle_id AND b.status='completed' GROUP BY c.name,v.reg_number) q;
CREATE OR REPLACE VIEW v_revenue_change AS SELECT month,net_revenue,net_revenue-LAG(net_revenue) OVER(ORDER BY month) change_vs_previous FROM mv_monthly_revenue;
CREATE OR REPLACE VIEW v_never_booked AS SELECT v.reg_number,v.make,v.model FROM vehicles v LEFT JOIN bookings b USING(vehicle_id) WHERE b.booking_id IS NULL;
CREATE OR REPLACE VIEW v_overdue_returns AS WITH overdue AS(SELECT r.rental_id,b.vehicle_id,b.customer_id,upper(b.period) due_at FROM rentals r JOIN bookings b USING(booking_id) WHERE r.return_at IS NULL AND upper(b.period)<now()) SELECT o.rental_id,v.reg_number,u.full_name,u.phone,now()-o.due_at overdue_by FROM overdue o JOIN vehicles v USING(vehicle_id) JOIN users u ON u.user_id=o.customer_id;
